def deleteAllActivationKeys(server):
    """
    Delete all activation keys from Spacewalk

    CLI Example:

    .. code-block:: bash

        salt-run spacewalk.deleteAllActivationKeys spacewalk01.domain.com
    """
    server = _check_server(server)
    try:
        keys = list(server.activation_keys())
    except Exception as exc:
        raise CommandExecutionError(
            "Could not list activation keys: {0}".format(exc)
        )
    if keys:
        try:
            for key in keys:
                server.delete_activation_key(key)
        except Exception as exc:
            raise CommandExecutionError(
                "Could not delete activation key: {0}".format(exc)
            )
    return True

